import Docxtemplater from 'docxtemplater';
import PizZip from 'pizzip';

/**
 * Convert raw score (0-20) to IELTS Band (0-9)
 * Based on official IELTS Placement Test conversion table
 */
export const scoreToIELTSBand = (rawScore, outOf = 20) => {
  if (rawScore === undefined || rawScore === null) return 0;
  
  // For Listening/Reading (out of 20)
  if (outOf === 20) {
    if (rawScore >= 19) return 6.5;  // 19-20 → 6.5
    if (rawScore >= 17) return 6.0;  // 17-18 → 6.0
    if (rawScore >= 15) return 5.5;  // 15-16 → 5.5
    if (rawScore >= 13) return 5.0;  // 13-14 → 5.0
    if (rawScore >= 10) return 4.5;  // 10-12 → 4.5
    if (rawScore >= 7) return 4.0;   // 7-9 → 4.0
    if (rawScore >= 5) return 3.5;   // 5-6 → 3.5
    if (rawScore >= 3) return 3.0;   // 3-4 → 3.0
    if (rawScore >= 1) return 2.5;   // 1-2 → <=2.5
    return 0;                         // 0 → 0
  }
  
  // For other scales, convert proportionally
  const percentage = (rawScore / outOf) * 100;
  
  if (percentage >= 95) return 6.5;
  if (percentage >= 85) return 6.0;
  if (percentage >= 75) return 5.5;
  if (percentage >= 65) return 5.0;
  if (percentage >= 50) return 4.5;
  if (percentage >= 35) return 4.0;
  if (percentage >= 25) return 3.5;
  if (percentage >= 15) return 3.0;
  if (percentage >= 5) return 2.5;
  if (percentage > 0) return 2.0;
  return 0;
};

/**
 * Calculate overall band score (average)
 */
export const calculateOverallBand = (listeningBand, readingBand, writingBand, speakingBand, grammarBand) => {
  const bands = [listeningBand, readingBand, writingBand, speakingBand, grammarBand].filter(b => b > 0);
  if (bands.length === 0) return 0;
  
  const avg = bands.reduce((a, b) => a + b, 0) / bands.length;
  // Round to nearest 0.5
  return Math.round(avg * 2) / 2;
};

/**
 * Get class level based on overall band score
 * Returns English-only text to avoid encoding issues
 */
export const getClassLevel = (overallBand) => {
  if (overallBand >= 7.5) return "Master (7.5+)";
  if (overallBand >= 6.5) return "Voyager (6.5-7.0)";
  if (overallBand >= 5.5) return "Voyager (5.5-6.0)";
  if (overallBand >= 4.5) return "Navigator (4.5-5.0)";
  if (overallBand >= 3.5) return "Explorer (3.5-4.0)";
  return "Beginner (<3.5)";
};

/**
 * Remove Vietnamese diacritics for PDF encoding compatibility
 */
const removeVietnameseDiacritics = (str) => {
  if (!str) return str;
  
  const vietnameseMap = {
    'à': 'a', 'á': 'a', 'ạ': 'a', 'ả': 'a', 'ã': 'a',
    'â': 'a', 'ầ': 'a', 'ấ': 'a', 'ậ': 'a', 'ẩ': 'a', 'ẫ': 'a',
    'ă': 'a', 'ằ': 'a', 'ắ': 'a', 'ặ': 'a', 'ẳ': 'a', 'ẵ': 'a',
    'è': 'e', 'é': 'e', 'ẹ': 'e', 'ẻ': 'e', 'ẽ': 'e',
    'ê': 'e', 'ề': 'e', 'ế': 'e', 'ệ': 'e', 'ể': 'e', 'ễ': 'e',
    'ì': 'i', 'í': 'i', 'ị': 'i', 'ỉ': 'i', 'ĩ': 'i',
    'ò': 'o', 'ó': 'o', 'ọ': 'o', 'ỏ': 'o', 'õ': 'o',
    'ô': 'o', 'ồ': 'o', 'ố': 'o', 'ộ': 'o', 'ổ': 'o', 'ỗ': 'o',
    'ơ': 'o', 'ờ': 'o', 'ớ': 'o', 'ợ': 'o', 'ở': 'o', 'ỡ': 'o',
    'ù': 'u', 'ú': 'u', 'ụ': 'u', 'ủ': 'u', 'ũ': 'u',
    'ư': 'u', 'ừ': 'u', 'ứ': 'u', 'ự': 'u', 'ử': 'u', 'ữ': 'u',
    'ỳ': 'y', 'ý': 'y', 'ỵ': 'y', 'ỷ': 'y', 'ỹ': 'y',
    'đ': 'd', 'Đ': 'D',
  };
  
  return str.split('').map(char => vietnameseMap[char] || char).join('');
};

/**
 * Fetch PDF template from Firebase Storage using direct URL with token
 * Token ensures authentication and bypasses CORS
 */
export const fetchPDFTemplate = async (driveFileId) => {
  try {
    console.log("📥 Fetching PDF from Firebase Storage...");
    
    // Direct Firebase Storage URL with access token
    const pdfUrl = 'https://firebasestorage.googleapis.com/v0/b/weaver-test-online.appspot.com/o/exam-templates%2FIELTS-template.pdf?alt=media&token=becaffc1-7570-4d78-bf92-198339131379';
    
    // Fetch PDF using authenticated URL (no CORS issues with token!)
    const response = await fetch(pdfUrl);
    
    if (!response.ok) {
      throw new Error(`Failed to fetch PDF: ${response.status} ${response.statusText}`);
    }
    
    const pdfBytes = await response.arrayBuffer();
    console.log("✅ PDF template fetched successfully:", pdfBytes.byteLength, "bytes");
    
    return pdfBytes;
  } catch (error) {
    console.error('❌ Error fetching PDF template:', error);
    console.warn('⚠️ PDF generation will be skipped');
    throw error;
  }
};

