/**
 * Extract scores from summary and answers
 * @param {Object} summary - Grading summary from gradeExam()
 * @param {Object} answers - User answers
 * @returns {Object} Extracted scores
 */
export const extractScoresFromGradeData = (summary, answers) => {
  const scores = {
    listeningRaw: 0,
    readingRaw: 0,
    writingScores: { taskResponse: 0, coherence: 0, lexical: 0, grammar: 0 },
    speakingRaw: 0,
    grammarVocabRaw: 0,
  };
  
  if (summary?.sections) {
    // Extract listening score (use actual correct count, not percentage)
    if (summary.sections.listening) {
      scores.listeningRaw = summary.sections.listening.correct || 0;
    }
    
    // Extract reading score
    if (summary.sections.reading) {
      scores.readingRaw = summary.sections.reading.correct || 0;
    }
    
    // Extract writing score (if available, otherwise estimate from grammar)
    if (summary.sections.writing) {
      const writingScore = summary.sections.writing.score;
      // Estimate individual criteria (in real case, these should be provided separately)
      const criteriaScore = (typeof writingScore === 'number' && Number.isFinite(writingScore))
        ? Math.round((writingScore / 100) * 5)
        : 0;
      scores.writingScores = {
        taskResponse: criteriaScore,
        coherence: criteriaScore,
        lexical: criteriaScore,
        grammar: criteriaScore,
      };
    }
    
    // Extract speaking score
    if (summary.sections.speaking) {
      scores.speakingRaw = summary.sections.speaking.correct || 0;
    }
    
    // Extract grammar/vocab score
    if (summary.sections.grammar) {
      scores.grammarVocabRaw = summary.sections.grammar.correct || 0;
    }
  }
  
  return scores;
};

/**
 * Fill Word/PDF template with student data
 * Template should have placeholders: {studentName}, {examDate}, {listenRaw}, etc.
 * 
 * @param {ArrayBuffer} template - DOCX template buffer
 * @param {Object} data - Student data
 * @returns {Promise<Blob>} - Filled document blob
 */
export const fillPDFTemplate = async (template, data) => {
  try {
    // Extract scores from data
    const {
      studentName = 'N/A',
      examDate = new Date().toLocaleDateString('vi-VN'),
      listeningRaw = 0,
      readingRaw = 0,
      writingScores = { taskResponse: 0, coherence: 0, lexical: 0, grammar: 0 },
      speakingRaw = 0,
      grammarVocabRaw = 0,
    } = data;
    
    // Calculate band scores
    const listeningBand = scoreToIELTSBand(listeningRaw, 20);
    const readingBand = scoreToIELTSBand(readingRaw, 20);
    const speakingBand = scoreToIELTSBand(speakingRaw, 20);
    const grammarBand = scoreToIELTSBand(grammarVocabRaw, 20);
    
    const writingBand = scoreToIELTSBand(
      (writingScores.taskResponse + writingScores.coherence + writingScores.lexical + writingScores.grammar) / 4,
      5
    );
    
    const overallBand = calculateOverallBand(listeningBand, readingBand, writingBand, speakingBand, grammarBand);
    const classLevel = getClassLevel(overallBand);
    
    const sanitizedName = removeVietnameseDiacritics(studentName);
    
    // Load template
    const zip = new PizZip(template);
    const doc = new Docxtemplater(zip, {
      paragraphLoop: true,
      linebreaks: true,
      delimiters: { start: '{', end: '}' }, // Use single braces to avoid Word formatting issues
    });
    
    // Fill data
    doc.render({
      studentName: sanitizedName,
      examDate: examDate,
      listenRaw: `${listeningRaw}/20`,
      listenBand: listeningBand.toFixed(1),
      readRaw: `${readingRaw}/20`,
      readBand: readingBand.toFixed(1),
      writeScores: `TR:${writingScores.taskResponse} CC:${writingScores.coherence} LR:${writingScores.lexical} GA:${writingScores.grammar}`,
      writeBand: writingBand.toFixed(1),
      speakRaw: `${speakingRaw}/20`,
      speakBand: speakingBand.toFixed(1),
      gramRaw: `${grammarVocabRaw}/20`,
      gramBand: grammarBand.toFixed(1),
      overallBand: overallBand.toFixed(1),
      classLevel: classLevel,
    });
    
    const output = doc.getZip().generate({
      type: 'blob',
      mimeType: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
    });
    
    console.log('✅ Document filled successfully');
    return output;
  } catch (error) {
    console.error('Error filling PDF template:', error);
    throw error;
  }
};

/**
 * Download file (DOCX or PDF)
 */
export const downloadFile = (fileBuffer, filename = 'ielts-result.docx', mimeType = 'application/vnd.openxmlformats-officedocument.wordprocessingml.document') => {
  const blob = fileBuffer instanceof Blob ? fileBuffer : new Blob([fileBuffer], { type: mimeType });
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = filename;
  link.click();
  URL.revokeObjectURL(url);
};

/**
 * Preview file in new tab (DOCX will download, PDF will open)
 */
export const previewFile = (fileBuffer, filename = 'ielts-result.docx', mimeType = 'application/vnd.openxmlformats-officedocument.wordprocessingml.document') => {
  const blob = fileBuffer instanceof Blob ? fileBuffer : new Blob([fileBuffer], { type: mimeType });
  const url = URL.createObjectURL(blob);
  
  // For DOCX, download directly
  if (mimeType.includes('wordprocessingml')) {
    const link = document.createElement('a');
    link.href = url;
    link.download = filename;
    link.click();
  } else {
    // For PDF, open in new tab
    window.open(url, '_blank');
  }
  
  URL.revokeObjectURL(url);
};
